# -*- coding: utf-8 -*-
from _lib import *
MM='Manuel des Monstres 5e (2014)'
VG='Volo’s Guide to Monsters (2016) et Manuel des Monstres 5e (2014)'
I(2,'Dans D&D 5e, lequel de ces monstres n’est pas de type « géant » ?','Minotaure',['Ogre','Ettin','Troll'],'Le minotaure est une monstruosité. L’ogre, l’ettin et le troll sont, en 5e, des créatures de type géant.',MM+', entrées « Minotaure », « Ogre », « Ettin », « Troll »')
I(3,'Lequel de ces modules n’est pas centré sur des géants ?','Tomb of Annihilation',['Against the Giants','Storm King’s Thunder','Steading of the Hill Giant Chief'],'Tomb of Annihilation (2017) se déroule dans la jungle de Chult. Les trois autres mettent les géants au premier plan.','Catalogue des modules D&D (TSR / Wizards of the Coast)')
T(1,'Dans D&D 5e, le troll se régénère, sauf s’il subit des dégâts d’acide ou de ____.','feu',['froid','tonnerre','poison'],'La régénération du troll (10 PV par tour) est stoppée pendant un tour par des dégâts d’acide ou de feu.',MM+', entrée « Troll »')
T(2,'Dans D&D 5e, au sommet de l’Ordning, la hiérarchie sociale des géants, règnent les géants des ____.','tempêtes',['nuages','collines','pierres'],'L’Ordning place les géants des tempêtes au sommet, devant les géants des nuages, du feu, du givre, de pierre et des collines.',VG+', chapitre « Géants »')
T(3,'Dans D&D 5e, le dieu des géants du feu s’appelle ____.','Surtur',['Thrym','Annam','Grolantor'],'Surtur est le dieu des géants du feu ; Thrym celui des géants du givre, Grolantor celui des géants des collines, Annam le Père de Tous.',VG+', chapitre « Géants »')
M(2,'Dans D&D 5e, lesquels de ces monstres sont de taille Très grande (Huge) ? (plusieurs bonnes réponses)',['Géant des collines','Géant du feu','Géant des nuages'],['Ogre','Ettin'],'Les six grands géants sont de taille Très grande ; l’ogre et l’ettin sont de taille Grande.',MM+', entrées correspondantes')
M(3,'Dans D&D 5e, lesquels de ces géants ont un FP de 9 ou plus ? (plusieurs bonnes réponses)',['Géant du feu','Géant des nuages','Géant des tempêtes'],['Géant de pierre','Géant des collines'],'FP : feu 9, nuages 9, tempêtes 13 ; pierre 7 et collines 5 sont en dessous.',MM+', entrées correspondantes')
M(2,'Dans D&D 5e, lesquels de ces êtres sont des divinités des géants ? (plusieurs bonnes réponses)',['Annam','Surtur','Thrym'],['Moradin','Corellon'],'Annam, Surtur et Thrym sont des dieux des géants. Moradin est le dieu des nains, Corellon celui des elfes.',VG+', chapitre « Géants »')
O(2,'Classe ces géants par FP croissant (du moins au plus dangereux).',['Géant des collines','Géant de pierre','Géant du givre','Géant du feu','Géant des tempêtes'],'FP : collines 5, pierre 7, givre 8, feu 9, tempêtes 13.',MM+', blocs de caractéristiques')
O(3,'Classe ces géants selon l’Ordning, du sommet de la hiérarchie à sa base.',['Géant des tempêtes','Géant des nuages','Géant du feu','Géant du givre','Géant des collines'],'Ordning : tempêtes, nuages, feu, givre, pierre, collines (du plus au moins prestigieux).',VG+', chapitre « Géants »')
A(1,'Associe chaque géant à son milieu de vie.',[('Géant du givre','Glaciers'),('Géant du feu','Volcans'),('Géant des nuages','Châteaux célestes'),('Géant de pierre','Cavernes de montagne')],'Chaque géant vit dans le milieu qui l’inspire : glace, volcans, ciel ou montagne.',MM+', entrées correspondantes')
A(3,'Associe chaque géant à son dieu.',[('Géant du givre','Thrym'),('Géant du feu','Surtur'),('Géant de pierre','Skoraeus Stonebones'),('Géant des collines','Grolantor')],'Thrym (givre), Surtur (feu), Skoraeus Stonebones (pierre), Grolantor (collines).',VG+', chapitre « Géants »')
W(1,['Je suis une créature de grande taille, aux longs bras griffus.','Mes blessures se referment sous tes yeux.','Seuls l’acide et le feu m’empêchent de me régénérer.'],'Troll',['Ogre','Ettin','Gobelours'],'Le troll se régénère de 10 PV par tour, sauf contre l’acide et le feu.',MM+', entrée « Troll »')
W(2,['Je suis un géant brutal et repoussant.','J’ai deux têtes qui se disputent sans cesse.','Quand l’une dort, l’autre veille : on me surprend rarement.'],'Ettin',['Ogre','Troll','Cyclope'],'L’ettin a deux têtes ; l’une reste éveillée quand l’autre dort.',MM+', entrée « Ettin »')
W(2,['Je suis le plus puissant des six grands géants.','Je règne au sommet de l’Ordning.','Je commande la foudre et les tempêtes, sur la mer ou dans les nuages.'],'Géant des tempêtes',['Géant des nuages','Géant du feu','Géant de pierre'],'Le géant des tempêtes (FP 13) domine l’Ordning et manie la foudre.',MM+', entrée « Géant des tempêtes »')
save('geants-dnd','gea')
